cssCode:
.product-card {
   width: 180px; height: 240px; background: #fff; border-radius: 20px;
   display: flex; flex-direction: column; align-items: center; justify-content: center;
   animation: floatCard 3s infinite ease-in-out alternate;
   position: relative; overflow: hidden; font-family: sans-serif;
}
.shadow {
   width: 120px; height: 15px; background: rgba(0,0,0,0.1); border-radius: 50%;
   margin-top: 30px; animation: shadowScale 3s infinite ease-in-out alternate;
}
@keyframes floatCard { 
  0% { transform: translateY(0px); box-shadow: 0 15px 25px rgba(0,0,0,0.1); } 
  100% { transform: translateY(-20px); box-shadow: 0 35px 45px rgba(0,0,0,0.15); } 
}
@keyframes shadowScale {
  0% { transform: scale(1); opacity: 1; }
  100% { transform: scale(0.7); opacity: 0.5; }
}

